CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS courses(id TEXT PRIMARY KEY, code TEXT NOT NULL, name TEXT NOT NULL, term TEXT, source TEXT NOT NULL, url TEXT);
CREATE TABLE IF NOT EXISTS assessments(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), title TEXT NOT NULL, kind TEXT NOT NULL, due TEXT, source TEXT NOT NULL, url TEXT, missing INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assessment_metadata(assessment_id TEXT PRIMARY KEY REFERENCES assessments(id), weight REAL, earned REAL, possible REAL, estimated REAL NOT NULL, worked REAL NOT NULL, status TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), title TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, pinned INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notices(id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS assessment_due ON assessments(due);
CREATE INDEX IF NOT EXISTS session_start ON sessions(start);
INSERT OR IGNORE INTO schema_version VALUES(1);
